  "id": 27,
  "knowledge": "Temperature Reading Implications",
  "description": "Illustrates temperature readings and their conservation implications.",
  "definition": "Ideal for most collections is 18-22\u00b0C. Fluctuations greater than 2\u00b0C within 24 hours can stress materials. Values outside 10-30\u00b0C may indicate control failure."
}

{
  "id": 5,
  "knowledge": "Showcase Environmental Stability Rating (SESR)",
  "description": "Measures how well a showcase maintains stable environmental conditions.",
  "definition": "Calculated as: 10 - ((24-hour Temperature Variation + (24-hour Humidity Variation / 5) + Leak Rate) / 3). Higher scores indicate more stable showcases."
}

{
  "id": 11,
  "knowledge": "High-Value Artifact",
  "description": "Identifies artifacts with exceptional historical, cultural, or monetary value requiring special attention.",
  "definition": "An artifact is considered high-value if its insurance value exceeds $1,000,000 OR if both its historical significance and cultural scores are in the top 10% of all artifacts."
}

{
  "id": 13,
  "knowledge": "Environmental Instability Event",
  "description": "Identifies periods when showcase environmental conditions fluctuate beyond acceptable parameters.",
  "definition": "Occurs when the 24-hour temperature variation exceeds 1\u00b0C OR the 24-hour humidity variation exceeds 3% within a 24-hour period."
}

